PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY, telegram_id TEXT NOT NULL UNIQUE, first_name TEXT, username TEXT, currency TEXT NOT NULL DEFAULT 'THB', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('cash','bank','ewallet','investment','crypto')), balance_satang INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'THB', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX accounts_user_idx ON accounts(user_id);
CREATE TABLE categories (id TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('income','expense')), name TEXT NOT NULL, icon TEXT, is_default INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, kind, name));
CREATE INDEX categories_user_idx ON categories(user_id);
CREATE TABLE transactions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('income','expense','transfer','investment_buy','investment_sell','dividend','interest','refund','adjustment')), amount_satang INTEGER NOT NULL CHECK(amount_satang > 0), category_id TEXT REFERENCES categories(id) ON DELETE SET NULL, account_id TEXT NOT NULL REFERENCES accounts(id), destination_account_id TEXT REFERENCES accounts(id), description TEXT, transaction_date TEXT NOT NULL, idempotency_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, idempotency_key));
CREATE INDEX transactions_user_date_idx ON transactions(user_id, transaction_date DESC);
CREATE INDEX transactions_category_idx ON transactions(category_id);
CREATE INDEX transactions_account_idx ON transactions(account_id);
CREATE TABLE budgets (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, category_id TEXT NOT NULL REFERENCES categories(id), month TEXT NOT NULL, amount_satang INTEGER NOT NULL CHECK(amount_satang >= 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, category_id, month));
CREATE INDEX budgets_user_month_idx ON budgets(user_id, month);
CREATE TABLE sinking_funds (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, account_id TEXT REFERENCES accounts(id), name TEXT NOT NULL, target_satang INTEGER NOT NULL, current_satang INTEGER NOT NULL DEFAULT 0, monthly_contribution_satang INTEGER NOT NULL DEFAULT 0, due_date TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX sinking_user_idx ON sinking_funds(user_id);
CREATE TABLE goals (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, target_satang INTEGER NOT NULL, current_satang INTEGER NOT NULL DEFAULT 0, deadline TEXT, priority INTEGER NOT NULL DEFAULT 3 CHECK(priority BETWEEN 1 AND 5), monthly_contribution_satang INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX goals_user_idx ON goals(user_id);
CREATE TABLE recurring_transactions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, amount_satang INTEGER NOT NULL, category_id TEXT REFERENCES categories(id), account_id TEXT NOT NULL REFERENCES accounts(id), description TEXT, frequency TEXT NOT NULL CHECK(frequency IN ('weekly','monthly','yearly','custom')), interval_days INTEGER, start_date TEXT NOT NULL, end_date TEXT, next_run_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX recurring_due_idx ON recurring_transactions(active, next_run_at);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX audit_user_created_idx ON audit_logs(user_id, created_at DESC);
